{
  "understanding": {
    "purpose": "Present a ranked reference list of tall buildings, with comparable heights and supporting location, construction and descriptive information.",
    "tasks": [
      "Find a building by rank, name, city or country.",
      "Compare heights, floors and completion years across buildings.",
      "Read across a row to connect a building with its measurements, location and comments.",
      "Scan the ranking sequentially and read comments for context."
    ],
    "relations": [
      "Rank and name identify each building and should remain easy to associate.",
      "Metres and feet are equivalent expressions of height under a shared header.",
      "City and country jointly identify location; year and comments provide context for the building."
    ],
    "roles": [
      "The first column carries rank; Name identifies the subject of each row.",
      "Height and Floors are comparison fields; City, Country and Year support lookup and context.",
      "Comments contain longer prose, while the two-tier header groups the height units."
    ],
    "keep_whole": [
      "Ranks, height values, years and numeric identifiers within names.",
      "Individual words in names, locations and comments wherever width permits.",
      "Floor counts and their parenthetical qualifiers wherever practical."
    ],
    "may_wrap": [
      "Building names between words.",
      "Multiword cities and countries between words.",
      "Floor qualifiers and comments at natural word boundaries."
    ],
    "same_scale": [
      "The metre and foot columns should have similar widths.",
      "Rank and year are compact fields; names and comments need more room for text."
    ],
    "h_vs_v": "A viewport-width table avoids horizontal scrolling but forces severe word and number splitting, tall rows and difficult comparison. Wider layouts preserve meaningful units and reduce row height, at the cost of scrolling between identifiers and later fields."
  },
  "designs": [
    {
      "widths": [28, 65, 34, 34, 39, 38, 43, 32, 46],
      "strategy": "Fit all nine columns within 359px, accepting extensive splitting and very tall rows to keep every field accessible without horizontal scrolling."
    },
    {
      "widths": [37, 180, 61, 60, 95, 100, 110, 58, 220],
      "strategy": "Use a moderately wide scrolling table that prioritizes names and height comparisons while allowing natural wrapping in locations, floor details and comments."
    },
    {
      "widths": [37, 244, 61, 60, 182, 118, 167, 58, 130],
      "strategy": "Use a wide reference layout that keeps names, floor details and locations largely on one line while reserving a narrower wrapping column for comments."
    }
  ]
}
